import { motion } from 'framer-motion';

const Experience = () => {
  const data = [
    {
      company: "Machine Learning Training",
      role: "Hands-on ML Implementation",
      date: "Jun '25 - Jul '25",
      desc: "Applied SQL for data extraction and implemented ML workflows using Python, NumPy, and Scikit-learn[cite: 30, 32, 33]."
    },
    {
      company: "Lovely Professional University",
      role: "B.Tech Computer Science & Engineering",
      date: "Aug '23 - Present",
      desc: "Maintaining a CGPA of 7.65 while focusing on algorithmic thinking and structured problem solving[cite: 34, 43, 51]."
    }
  ];

  return (
    <section className="py-24 px-10 bg-gray-50">
      <div className="container mx-auto">
        <h3 className="text-4xl font-black mb-16 tracking-tighter">EXPERIENCE & EDUCATION</h3>
        <div className="space-y-12">
          {data.map((item, i) => (
            <motion.div 
              key={i}
              initial={{ opacity: 0, x: -20 }}
              whileInView={{ opacity: 1, x: 0 }}
              className="flex flex-col md:flex-row gap-4 md:gap-20 border-b border-gray-200 pb-12"
            >
              <div className="md:w-1/4">
                <p className="text-gray-400 font-bold uppercase tracking-widest text-sm">{item.date}</p>
              </div>
              <div className="md:w-3/4">
                <h4 className="text-2xl font-bold">{item.company}</h4>
                <p className="text-blue-600 font-bold mb-4">{item.role}</p>
                <p className="text-gray-600 max-w-2xl leading-relaxed">{item.desc}</p>
              </div>
            </motion.div>
          ))}
        </div>
      </div>
    </section>
  );
};

export default Experience;
